{
  "packet_id": "H6-T03-3",
  "claim_id": "C022",
  "status": "SUPPORTED",
  "claim": {
    "component_id": "C022.component",
    "value": "Unlocated records do not prove that approval never occurred.",
    "scope": "The evidentiary limit of failure to locate records.",
    "provenance": {
      "refs": [
        {
          "source_id": "P024",
          "role": "SUPPORT"
        }
      ],
      "support_status": "SUFFICIENT",
      "rationale": "The cited span explicitly states this limit on inference from unlocated records."
    }
  },
  "signal_basis": {
    "component_id": "C022.signal_basis",
    "value": "Review purchasing records, meeting minutes and delegated-authority forms for evidence of authorized approval before placement; failure to locate evidence alone leaves the historical case unresolved.",
    "scope": "Historical record searches for the flagged orders, distinguishing unsuccessful retrieval from evidence of late or absent approval.",
    "provenance": {
      "refs": [
        {
          "source_id": "P005",
          "role": "SUPPORT"
        },
        {
          "source_id": "P017",
          "role": "SUPPORT"
        }
      ],
      "support_status": "SUFFICIENT",
      "rationale": "These spans supply the record-review operation and explicitly classify unsuccessful retrieval alone as unresolved."
    }
  },
  "stated_empirical_relation": {
    "component_id": "C022.stated_empirical_relation",
    "value": "NOT_APPLICABLE",
    "scope": "NOT_APPLICABLE",
    "provenance": {
      "refs": [],
      "support_status": "SUFFICIENT",
      "rationale": "The claim is supported without requiring establishment of an unresolved empirical relation."
    }
  },
  "rationale": "A completed search that fails to locate approval evidence establishes an evidentiary gap. The mapping supplies no guarantee that every actual approval would leave a record recoverable by that search. The result therefore remains compatible with approval having occurred and licenses the stated limit on what unsuccessful retrieval proves.",
  "uncertainty": "Whether approval actually occurred remains unresolved; that uncertainty does not undermine this evidentiary limit.",
  "anomalies": []
}
